import{_ as a,o as e,c as r,a2 as i}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"传统 Web 项目接入 AI：旁路增强实战路径","description":"","frontmatter":{"title":"传统 Web 项目接入 AI：旁路增强实战路径","date":"2026-06-11T00:00:00.000Z","isComment":true,"categories":["AI","Frontend"],"tags":["Integration","Enterprise","Legacy"]},"headers":[],"relativePath":"24-traditional-web-ai-integration.md","filePath":"24-traditional-web-ai-integration.md","lastUpdated":1790425174000}'),d={name:"24-traditional-web-ai-integration.md"};function n(s,t,l,o,h,p){return e(),r("div",null,[...t[0]||(t[0]=[i(`<h1 id="传统-web-项目接入-ai-旁路增强实战路径" tabindex="-1">传统 Web 项目接入 AI：旁路增强实战路径 <a class="header-anchor" href="#传统-web-项目接入-ai-旁路增强实战路径" aria-label="Permalink to &quot;传统 Web 项目接入 AI：旁路增强实战路径&quot;">​</a></h1><blockquote><p>系列默认 Next.js + LangGraph。公司很多项目是 <strong>Vue/React 老站 + Java/Node 单体</strong>。这篇给 <strong>不改核心交易链路</strong> 的接入路径，对照本系列已写文章，按 90 天节奏落地。</p></blockquote><h2 id="📚-目录" tabindex="-1">📚 目录 <a class="header-anchor" href="#📚-目录" aria-label="Permalink to &quot;📚 目录&quot;">​</a></h2><ul><li><a href="#约束与原则">约束与原则</a></li><li><a href="#架构旁路-ai-层">架构：旁路 AI 层</a></li><li><a href="#八个切入点按优先级">八个切入点（按优先级）</a></li><li><a href="#三种落地架构">三种落地架构</a></li><li><a href="#与系列文章对照">与系列文章对照</a></li><li><a href="#90-天节奏">90 天节奏</a></li><li><a href="#反模式">反模式</a></li><li><a href="#系列导航">系列导航</a></li></ul><hr><h2 id="约束与原则" tabindex="-1">约束与原则 <a class="header-anchor" href="#约束与原则" aria-label="Permalink to &quot;约束与原则&quot;">​</a></h2><table tabindex="0"><thead><tr><th>典型现状</th><th>接入原则</th></tr></thead><tbody><tr><td>单体 Spring / Express</td><td>加 <code>/api/ai/*</code>，不拆核心包</td></tr><tr><td>Vue2 / jQuery 混用</td><td>前端只多调几个 HTTP</td></tr><tr><td>无向量库</td><td>先一个 RAG POC</td></tr><tr><td>不能重写下单支付</td><td><strong>LLM 不直接写库</strong></td></tr></tbody></table><p><strong>AI = 增强层</strong>，不是替换 ERP/商城核心。</p><div class="language-mermaid vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    FE[现有前端] --&gt; API[现有 API]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    FE --&gt; AI[&quot;/api/ai/*&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    AI --&gt; LLM[LLM]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API --&gt; DB[(业务库)]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    AI --&gt; Vec[(向量库 可选)]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><hr><h2 id="架构-旁路-ai-层" tabindex="-1">架构：旁路 AI 层 <a class="header-anchor" href="#架构-旁路-ai-层" aria-label="Permalink to &quot;架构：旁路 AI 层&quot;">​</a></h2><h3 id="最小-poc-2-周" tabindex="-1">最小 POC（2 周） <a class="header-anchor" href="#最小-poc-2-周" aria-label="Permalink to &quot;最小 POC（2 周）&quot;">​</a></h3><ol><li>选 <strong>只读</strong> 文档库（帮助中心 / 内部 Wiki）</li><li>索引脚本 + <code>POST /api/ai/chat</code>（RAG 固定链，无 Agent）</li><li>现有页加「智能问答」抽屉</li></ol><p>对应阅读：<a href="./rag-blog-knowledge-search">RAG 实战</a> · <a href="./langchain/">LC 06～09</a></p><h3 id="标准助手-1-2-月" tabindex="-1">标准助手（1～2 月） <a class="header-anchor" href="#标准助手-1-2-月" aria-label="Permalink to &quot;标准助手（1～2 月）&quot;">​</a></h3><ol><li>LangGraph ReAct + <code>search</code> Tool 包现有 REST（只读）</li><li>checkpoint + <a href="./17-build-production-chatbot-ui">17 Chatbot UI</a></li><li><a href="./18-agent-production-checklist">18 上线清单</a> + <a href="./langgraph/13-redis-neon-deployment">LG 13</a></li></ol><h3 id="企业内网" tabindex="-1">企业内网 <a class="header-anchor" href="#企业内网" aria-label="Permalink to &quot;企业内网&quot;">​</a></h3><ul><li>模型走 <strong>私有网关</strong>（<a href="./langchain/02-chat-models">LC 02 baseURL</a>）</li><li>数据不出域；Eval 内网 LangSmith 或日志</li></ul><hr><h2 id="八个切入点-按优先级" tabindex="-1">八个切入点（按优先级） <a class="header-anchor" href="#八个切入点-按优先级" aria-label="Permalink to &quot;八个切入点（按优先级）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>场景</th><th>风险</th><th>系列参考</th></tr></thead><tbody><tr><td>1</td><td>文档语义搜索 / 问答</td><td>低</td><td>RAG 实战、11、LC 12</td></tr><tr><td>2</td><td>侧边栏 Copilot（只读 Tool）</td><td>低</td><td><a href="./26-copilotkit-guide">26 CopilotKit</a>、16、LG 04、<a href="./17-build-production-chatbot-ui">17 UI</a></td></tr><tr><td>3</td><td>表单旁「润色/总结」按钮</td><td>低</td><td>LC 02 单次 invoke</td></tr><tr><td>4</td><td>工单分类打标</td><td>中</td><td>LC 10 Parser、22 Eval</td></tr><tr><td>5</td><td>自然语言查报表 API</td><td>中</td><td>09 Tools、LC 05</td></tr><tr><td>6</td><td>审批流 + interrupt</td><td>中</td><td>LG 08、09</td></tr><tr><td>7</td><td>Multi-Agent 报表</td><td>高</td><td>12、LG 07</td></tr><tr><td>8</td><td>对外客服 Bot</td><td>高</td><td>18、22</td></tr></tbody></table><p><strong>先做 1～3</strong>，跑稳再 5～6。</p><hr><h2 id="三种落地架构" tabindex="-1">三种落地架构 <a class="header-anchor" href="#三种落地架构" aria-label="Permalink to &quot;三种落地架构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>做法</th><th>适合</th></tr></thead><tbody><tr><td><strong>BFF 旁路</strong></td><td>现有 Node/Java 加 <code>ai</code> 模块</td><td>不想新服务</td></tr><tr><td><strong>独立 ai-service</strong></td><td>主站 HTTP 调 AI 服务</td><td>多产品共用</td></tr><tr><td><strong>Serverless</strong></td><td>云函数处理对话</td><td>流量小、快试</td></tr></tbody></table><p>前端无关框架：<code>fetch</code> + SSE 与 <a href="./17-build-production-chatbot-ui">17</a> 相同；Vue 可复用 <code>useAgentStream</code> 逻辑。</p><h3 id="java-单体旁路示例-概念" tabindex="-1">Java 单体旁路示例（概念） <a class="header-anchor" href="#java-单体旁路示例-概念" aria-label="Permalink to &quot;Java 单体旁路示例（概念）&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>现有 Spring Boot</span></span>
<span class="line"><span>  ├── controller/OrderController   # 不动</span></span>
<span class="line"><span>  └── controller/AiChatController  # 新增，内调 LangGraph4j 或 HTTP 转 Node ai-service</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Node 栈可直接 <a href="./langgraph/12-full-route-example">LG 12 Route</a> 嵌进 Express。</p><hr><h2 id="与系列文章对照" tabindex="-1">与系列文章对照 <a class="header-anchor" href="#与系列文章对照" aria-label="Permalink to &quot;与系列文章对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你想在公司做</th><th>先读</th></tr></thead><tbody><tr><td>要不要 LangChain</td><td><a href="./15-langchain-js-guide">15 生态</a></td></tr><tr><td>图编排</td><td><a href="./16-langgraphjs-practice">16</a>、LG 专系列</td></tr><tr><td>Chat 组件</td><td><a href="./17-build-production-chatbot-ui">17</a> 或 <a href="./20-vercel-ai-sdk-guide">20 Vercel AI SDK</a>（Next 项目）</td></tr><tr><td>上线</td><td><a href="./18-agent-production-checklist">18</a></td></tr><tr><td>用 Cursor 加速开发</td><td><a href="./skills-guide">Skills 指南</a>、<a href="./23-skills-agent-bridge">23</a></td></tr><tr><td>质量</td><td><a href="./22-agent-eval-regression">22 Eval</a></td></tr></tbody></table><hr><h2 id="_90-天节奏" tabindex="-1">90 天节奏 <a class="header-anchor" href="#_90-天节奏" aria-label="Permalink to &quot;90 天节奏&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>交付</th></tr></thead><tbody><tr><td><strong>月 1</strong></td><td>只读 RAG 问答内网；数据权限规则</td></tr><tr><td><strong>月 2</strong></td><td>2～3 个表单 AI 按钮；3 个只读 API Tool</td></tr><tr><td><strong>月 3</strong></td><td>Copilot UI + 限流 + Trace；10 条 Eval golden</td></tr></tbody></table><p>之后按需 Multi-Agent、对外 Bot（<a href="./12-multi-agent-systems">12</a>）。</p><hr><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>一上来「一个 Agent 管全站」</li><li>LLM 直接改订单、库存、支付</li><li>无审计把内部数据喂公网模型</li><li>为 AI 整站重构成 Next（除非本来就要重构）</li><li>跳过 POC 买企业 Agent 平台却不接现有 API</li></ul><hr><h2 id="系列导航" tabindex="-1">系列导航 <a class="header-anchor" href="#系列导航" aria-label="Permalink to &quot;系列导航&quot;">​</a></h2><p><strong>Agent 主线：</strong> <a href="./07-ai-agent-architecture">07</a> → <a href="./08-build-first-agent">08</a> → … → <a href="./19-blog-ai-assistant-capstone">19 收官</a></p><p><strong>Phase 2：</strong> <a href="./20-vercel-ai-sdk-guide">20 SDK</a> · <a href="./21-multimodal-interaction">21 多模态</a> · <a href="./22-agent-eval-regression">22 Eval</a> · <a href="./23-skills-agent-bridge">23 Skills</a> · <strong>本文</strong></p><p><strong>总索引：</strong> <a href="/">README</a> · <strong>路线图：</strong> <a href="./ai-agent-learning-roadmap">ai-agent-learning-roadmap</a></p>`,44)])])}const b=a(d,[["render",n]]);export{g as __pageData,b as default};
